-- GASP dataset invoice (snapshot; Invoice). snapshot rows on month starts, month ends and the period bounds shifted back by one, three, six and twelve months
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.invoice (
  billing_trigger_date DATE,
  credit_memo_count INTEGER,
  currency VARCHAR(1000),
  customer_id VARCHAR(1000),
  invoice_amount DECIMAL(18, 6),
  invoice_corrected BOOLEAN,
  invoice_date DATE,
  invoice_disputed BOOLEAN,
  invoice_id VARCHAR(1000),
  outstanding_amount DECIMAL(18, 6),
  payment_date DATE,
  payment_method VARCHAR(1000),
  payment_status VARCHAR(1000),
  snapshot_date DATE
);
